function caseImage(file,alt,caption=''){return `<figure class="case-figure"><a href="assets/${file}" target="_blank" rel="noopener" aria-label="${alt} 크게 보기"><img src="assets/${file}" alt="${alt}" loading="lazy" decoding="async"></a>${caption?`<figcaption>${caption}</figcaption>`:''}</figure>`}
function caseSection(num,title,body){return `<section class="case-section"><div class="case-heading"><span>${num}</span><h2>${title}</h2></div>${body}</section>`}
function renderCase(p){const c=caseStudies[p.id];const cards=(list,className='')=>`<div class="case-cards ${className}">${list.map(([title,body],i)=>`<div class="case-card"><span class="case-num">0${i+1}</span><h3>${title}</h3><p>${body}</p></div>`).join('')}</div>`;const practiceCards=(list)=>`<div class="case-cards practice-cards">${list.map(([title,body,file,caption],i)=>`<div class="case-card practice-card"><div class="practice-copy"><span class="case-num">0${i+1}</span><h3>${title}</h3><p>${body}</p></div>${caseImage(file,caption,caption)}</div>`).join('')}</div>`;const aiopsPracticeCards=(list)=>`<div class="case-cards practice-cards aiops-practice-cards">${list.map(([title,body,media],i)=>`<div class="case-card practice-card aiops-practice-card ${media.length?'':'no-media'}"><div class="practice-copy"><span class="case-num">0${i+1}</span><h3>${title}</h3><p>${body}</p></div>${media.length?`<div class="practice-media ${media.length>1?'dual':''}">${media.map(([file,caption])=>caseImage(file,caption,caption)).join('')}</div>`:''}</div>`).join('')}</div>`;
let evidence='';
if(p.id==='bememory') evidence=`<div class="evidence-grid"><div class="case-panel"><div class="eyebrow">SERVER MIGRATION</div><h3>Lambda → EC2</h3><p>K6 부하 테스트 · 7,500건 요청 처리 시 p95 응답시간</p><div class="comparison" role="img" aria-label="Lambda 65밀리초, EC2 t3.micro 25밀리초"><div class="bar-row"><span>Lambda</span><div class="bar-track"><i style="width:100%"></i></div><strong>65 ms</strong></div><div class="bar-row"><span>EC2 (t3.micro)</span><div class="bar-track"><i style="width:38.46%"></i></div><strong>25 ms</strong></div></div></div><div class="case-panel observability-panel"><div class="eyebrow">OBSERVABILITY</div><h3>로그 적재와 모니터링</h3><div class="service-group"><span>Firehose</span><span>Log stream</span><span>Insights</span><strong>CloudWatch</strong></div><p>키오스크 로그와 요청 현황을 확인할 수 있는 운영 관측 환경을 구성했습니다.</p><div class="observability-shots">${caseImage('monitoring.jpg','CloudWatch 요청 수와 응답시간 모니터링 화면','CloudWatch 대시보드')}${caseImage('kiosk-logs.jpg','키오스크 로그 조회 화면','키오스크 로그 조회')}</div></div></div>`;
if(p.id==='cgv') evidence=`<div class="case-cards practice-cards cgv-evidence-cards"><div class="case-card practice-card"><div class="practice-copy"><div class="eyebrow">DISASTER RECOVERY</div><h3>멀티 리전으로 서비스 연속성 확보</h3><p>서울 리전 장애 상황에서도 도쿄 리전에서 서비스를 이어갈 수 있도록 Pilot Light 전략의 DR 환경을 구성했습니다.</p></div>${caseImage('dr.jpg','서울과 도쿄 리전의 DR 아키텍처','멀티 리전 DR · Pilot Light 전략')}</div><div class="case-card practice-card"><div class="practice-copy"><div class="eyebrow">ASYNCHRONOUS PROCESSING</div><h3>중복 예매 방지와 비동기 처리</h3><p>Redis로 중복 요청을 제어하고 Kafka로 요청을 비동기 처리해 트래픽 급증 상황에서도 예약 데이터를 안정적으로 반영하도록 구성했습니다.</p></div>${caseImage('async.jpg','Redis와 Kafka를 활용한 예매 처리 아키텍처','비동기 예매 처리 구성도')}</div></div>`;
if(p.id==='vmware') evidence=`<div class="case-panel"><div class="eyebrow">LAB FLOW</div><h3>기초부터 클러스터 운영까지 확장한 홈랩</h3><p>ESXi 설치와 중앙 관리 환경을 시작으로 가상 네트워크, 공유 스토리지, 가상 머신 이동과 고가용성까지 단계적으로 실습했습니다.</p><ol class="process-list"><li>ESXi 환경 구성</li><li>vCenter 중앙 관리</li><li>vDS·NFS 연결</li><li>vMotion·HA 학습</li></ol></div>`;
if(p.id==='info') evidence=`<div class="screen-grid">${[['sns-board.jpg','재학생 커뮤니티','게시판 CRUD API를 통해 정보를 작성하고 나누는 공간을 구현했습니다.'],['sns-room.jpg','빈 강의실 게시판','시간대별 강의실 사용 현황을 조회할 수 있도록 구성했습니다.'],['sns-alumni.jpg','졸업생 태그','졸업생을 구분해 재학생과의 소통을 돕습니다.']].map(([f,t,b])=>`<section><h3>${t}</h3><p>${b}</p>${caseImage(f,t+' 실제 서비스 화면')}</section>`).join('')}</div>`;
const insightExtra=p.id==='cgv'?`<div class="load-test-insight"><div class="load-test-copy"><div class="eyebrow">LOAD TEST RESULT</div><h3>1,000 TPS당 약 0.6&nbsp;vCPU</h3><p>부하 테스트 결과를 바탕으로 트래픽 1,000 TPS를 처리하는 데 필요한 CPU 리소스를 약 0.6 vCPU로 산정했습니다.</p><div class="load-metric" aria-label="1,000 TPS당 0.6 vCPU"><strong>1,000</strong><span>TPS</span><i>→</i><strong>0.6</strong><span>vCPU</span></div></div>${caseImage('load-test.jpg','CGV 부하 테스트 결과 원본 화면','부하 테스트 수행 결과')}</div>`:'';
if(p.id==='vmware') return `<article class="detail case-study ${p.id}"><a class="back" href="#toy">← Toy Project</a><div class="eyebrow">${p.category}</div><h1>${p.name}</h1><p class="case-lead">${c.goal}</p><p class="detail-intro">${p.intro}</p><div class="case-role"><h2>실습 내용</h2><ul>${p.tasks.map(t=>`<li>${t}</li>`).join('')}</ul></div><div class="stack-chips" aria-label="기술 스택">${p.stack.split(' · ').map(t=>`<span>${t}</span>`).join('')}</div>${caseSection('01','Architecture',caseImage(p.image,p.name+' 전체 아키텍처','구성도를 누르면 크게 볼 수 있습니다.'))}${caseSection('02','Practice',evidence+practiceCards(c.solutions))}${caseSection('03','Learn',cards(c.learn,'learn-list'))}${p.links.length?`<div class="links case-links">${p.links.map(([n,u])=>`<a href="${u}" target="_blank" rel="noopener">${n} ↗</a>`).join('')}</div>`:''}<a class="back case-end" href="#toy">← 프로젝트 목록으로</a></article>`;
if(p.id==='aiops'){const pipeline=`<div class="case-panel aiops-flow"><div class="eyebrow">HUMAN-IN-THE-LOOP PIPELINE</div><h3>관측부터 승인·복구·검증까지</h3><p><mark class="aiops-highlight">자동 수집과 점검 결과를 AI가 읽기 전용으로 조회하고, 사람이 승인한 복구만 실행하도록 진단과 변경 권한을 분리했습니다.</mark></p><ol class="process-list"><li>지표·로그 수집</li><li>MCP·RAG 진단</li><li>사람 승인</li><li>Ansible 복구·검증</li></ol></div>`;const scenario=`<div class="scenario-grid"><div class="case-panel"><div class="eyebrow">FAULT INJECTION</div><h3>Node Exporter 단독 장애 재현</h3><p>Node Exporter 중단으로 서비스는 정상 작동하지만 모니터링 지표만 누락되는 부분 장애를 재현했습니다.</p><div class="state-flow"><span>NORMAL</span><i>→</i><span>CRITICAL</span><i>→</i><span>WARNING</span><i>→</i><span>NORMAL</span></div></div><div class="case-panel scenario-wide"><div class="eyebrow">DETECTION · DIAGNOSIS · RECOVERY</div><h3>탐지·승인·복구 구간의 근거</h3><div class="metric-strip"><div><strong>41초</strong><span>자동 점검 시작</span></div><div><strong>51초</strong><span>3회 재시도 후 장애 기록</span></div><div><strong>7초</strong><span>승인 후 Ansible 복구</span></div></div><ol class="scenario-timeline">
<li><time>09:27:39</time><div><strong>사람 · 장애 주입</strong><p>linux-c에서 Node Exporter를 중지</p></div></li>
<li><time>09:28:20</time><div><strong>systemd timer · 자동 점검 시작</strong><p>1분 주기로 health_check.py 실행</p></div></li>
<li class="scenario-before-claude"><time>09:28:30</time><div><strong>Python 헬스체크 · 장애 기록</strong><p>3회 연결 실패 후 health_check.log에 장애 결과와 종료 코드 1 기록</p></div></li>
<li class="scenario-claude-request"><span class="scenario-claude-icon"><img src="assets/clawd.png" alt="" aria-hidden="true"></span><div><strong>Claude에게 진단 요청</strong></div></li>
<li><time>진단</time><div><strong>Claude · aiops-monitor MCP 호출</strong><p>호출 시점에 Prometheus 지표, Loki ready, 최근 헬스체크 로그를 실시간 조회</p></div></li>
<li><time>검색</time><div><strong>Claude · aiops-knowledge MCP 호출</strong><p>Qdrant에서 관련 Runbook과 과거 장애 청크를 RAG 검색</p></div></li>
<li><time>분석</time><div><strong>AI · 장애 진단 보고서 작성</strong><p>CRITICAL 판정, 영향 범위, 원인 후보와 승인 기반 복구 절차 제안</p></div></li>
<li><time>승인</time><div><strong>사람 · 보고서 검토 및 승인</strong><p>APPROVE NODE_EXPORTER RECOVERY 입력</p></div></li>
<li><time>복구</time><div><strong>Ansible · 승인된 복구 실행</strong><p>서비스 활성화·시작, 9100 포트와 HTTP 응답 확인</p></div></li>
<li><time>검증</time><div><strong>자동 검증</strong><p>Prometheus up=1, 헬스체크 종료 코드 0, 메모리·디스크 지표 재수집 확인</p></div></li>
</ol><p class="scenario-summary">systemd 기반 자동 헬스체크가 장애를 51초 만에 기록했으며, 이후 사람이 Claude에 진단을 요청하자 AI가 MCP와 RAG로 운영 데이터와 지식을 조회해 CRITICAL로 진단했습니다.</p></div></div>`;return `<article class="detail case-study ${p.id}"><a class="back" href="#toy">← Toy Project</a><div class="aiops-hero"><div class="aiops-hero-copy"><div class="eyebrow">${p.category}</div><h1>${p.name}</h1><p class="case-lead">${c.goal}</p><p class="detail-intro">${p.intro}</p></div><img class="aiops-hero-mascot" src="assets/clawd.png" alt="Claude 캐릭터" width="180" height="180"></div><div class="aiops-focus-box"><p>매트릭 수집 MCP만 사용했을 때는 장애와 영향 범위를 파악할 수 있었지만, 에이전트는 일반적인 Linux 지식을 바탕으로 우리 환경에 맞는 복구 방법과 해결책을 제시하는데 한계가 있었습니다. 이를 보완하기 위해 Runbook과 과거 장애 보고서를 만들고, 필요한 운영 지식을 검색해 제공하는 방식으로 실험을 확장했습니다.</p></div><div class="case-role"><h2>실습 내용</h2><ul>${p.tasks.map(t=>`<li>${t}</li>`).join('')}</ul></div><div class="stack-chips" aria-label="기술 스택">${p.stack.split(' · ').map(t=>`<span>${t}</span>`).join('')}</div>${caseSection('01','Architecture',caseImage(p.detailImage||p.image,p.name+' 전체 아키텍처','구성도를 누르면 크게 볼 수 있습니다.'))}${caseSection('02','Pipeline',pipeline+aiopsPracticeCards(c.practices))}${caseSection('03','Scenario',scenario)}${caseSection('04','Learn',cards(c.learn,'learn-list'))}<a class="back case-end" href="#toy">← 프로젝트 목록으로</a></article>`}
return `<article class="detail case-study ${p.id}"><a class="back" href="#main">← Main Project</a><div class="eyebrow">${p.category}</div><h1>${p.name}</h1><p class="case-lead">${c.goal}</p><p class="detail-intro">${p.intro}</p><dl class="facts"><div><dt>PERIOD</dt><dd>${p.period}</dd></div><div><dt>ORGANIZATION</dt><dd>${p.org}</dd></div><div><dt>TEAM</dt><dd>${p.people}</dd></div></dl><div class="case-role"><h2>담당한 일</h2><ul>${p.tasks.map(t=>`<li>${t}</li>`).join('')}</ul></div><div class="stack-chips" aria-label="기술 스택">${p.stack.split(' · ').map(t=>`<span>${t}</span>`).join('')}</div>${caseSection('01','Problem',cards(c.problems))}${p.id!=='info'?caseSection('02','Architecture',(p.id==='bememory'?diagramViewer():caseImage(p.image,p.name+' 전체 아키텍처','구성도를 누르면 크게 볼 수 있습니다.'))):''}${caseSection(p.id==='info'?'02':'03','Solution',cards(c.solutions)+evidence)}${caseSection(p.id==='info'?'03':'04','Insight',`<div class="insight-list">${c.insights.map(([problem,solution])=>`<div class="insight-row"><div><span>PROBLEM</span><p>${problem}</p></div><span class="insight-arrow" aria-hidden="true">→</span><div><span>SOLUTION</span><p>${solution}</p></div></div>`).join('')}</div>${insightExtra}`)}${p.links.length?`<div class="links case-links">${p.links.map(([n,u])=>`<a href="${u}" target="_blank" rel="noopener">${n} ↗</a>`).join('')}</div>`:''}<a class="back case-end" href="#main">← 프로젝트 목록으로</a></article>`}

function diagramViewer(){return `<figure class="case-figure architecture-static"><a href="assets/bememory-architecture.png" target="_blank" rel="noopener" aria-label="비메모리 AWS 인프라 아키텍처 크게 보기"><img src="assets/bememory-architecture.png" alt="비메모리 AWS 인프라 아키텍처" loading="eager" decoding="async"></a><figcaption>구성도를 누르면 원본 크기로 볼 수 있습니다.</figcaption></figure>`}
